INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Kundenbeziehungen > Konsequente Kundenausrichtung (Relationship Marketing)
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die konsequente Kundenausrichtung im Relationship Marketing ausschließlich auf den Verkauf neuer Produkte fokussiert?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus liegt auf langfristiger Beziehung, nicht nur Verkauf"}, {"text": "Ja", "correct": false, "because": "Beziehung steht über kurzfristigem Absatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Erfordert die konsequente Kundenausrichtung im Relationship Marketing eine individuelle Anpassung der Kommunikation?', 2, '[{"text": "Ja", "correct": true, "because": "Personalisierung stärkt die Bindung"}, {"text": "Nein", "correct": false, "because": "Standardkommunikation widerspricht dem Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die konsequente Kundenausrichtung im Relationship Marketing ohne Kundenfeedback erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Feedback ist essenziell für Anpassung"}, {"text": "Ja", "correct": false, "because": "Ohne Feedback fehlt die Orientierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es im Relationship Marketing notwendig, Kunden auch nach Vertragsabschluss aktiv zu betreuen?', 2, '[{"text": "Ja", "correct": true, "because": "Nachbetreuung fördert Loyalität"}, {"text": "Nein", "correct": false, "because": "Nur Vorverkauf wäre zu kurz gedacht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die konsequente Kundenausrichtung im Relationship Marketing kurzfristige Gewinne über langfristige Beziehungen stellen?', 2, '[{"text": "Nein", "correct": true, "because": "Langfristigkeit ist Kernprinzip"}, {"text": "Ja", "correct": false, "because": "Kurzfristigkeit widerspricht dem Konzept"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die konsequente Kundenausrichtung im Relationship Marketing primär?', 2, '[{"text": "Kundenloyalität", "correct": true, "because": "Langfristige Bindung ist zentral"}, {"text": "Schneller Umsatz", "correct": false, "because": "Kurzfristig, nicht primär"}, {"text": "Marktanteilserhöhung", "correct": false, "because": "Indirekt, nicht Hauptziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode ist im Relationship Marketing entscheidend, um die Kundenausrichtung sicherzustellen?', 3, '[{"text": "Personalisierte Angebote", "correct": true, "because": "Erfüllen individuelle Bedürfnisse"}, {"text": "Massenwerbung", "correct": false, "because": "Zu unpersönlich"}, {"text": "Preissenkungen", "correct": false, "because": "Nicht nachhaltig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element steht im Relationship Marketing im Vordergrund der konsequenten Kundenausrichtung?', 2, '[{"text": "Vertrauensaufbau", "correct": true, "because": "Basis für langfristige Beziehungen"}, {"text": "Produktvielfalt", "correct": false, "because": "Sekundär relevant"}, {"text": "Kosteneffizienz", "correct": false, "because": "Interner Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ressource ist im Relationship Marketing für die Kundenausrichtung unerlässlich?', 2, '[{"text": "Kundendaten", "correct": true, "because": "Ermöglicht Personalisierung"}, {"text": "Werbebudget", "correct": false, "because": "Wichtig, aber nicht zentral"}, {"text": "Produktentwickler", "correct": false, "because": "Technisch, nicht beziehungsorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorgehensweise widerspricht der konsequenten Kundenausrichtung im Relationship Marketing?', 2, '[{"text": "Einheitliche Standardantworten", "correct": true, "because": "Ignoriert Individualität"}, {"text": "Regelmäßige Kundenbefragungen", "correct": false, "because": "Fördert Ausrichtung"}, {"text": "Proaktive Kommunikation", "correct": false, "because": "Stärkt Beziehung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien prägen die konsequente Kundenausrichtung im Relationship Marketing?', 4, '[{"text": "Langfristigkeit", "correct": true, "because": "Fokus auf dauerhafte Beziehungen"}, {"text": "Individualisierung", "correct": true, "because": "Anpassung an Kundenbedürfnisse"}, {"text": "Vertrauen", "correct": true, "because": "Grundlage der Loyalität"}, {"text": "Massendistribution", "correct": false, "because": "Widerspricht Personalisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen unterstützen die konsequente Kundenausrichtung im Relationship Marketing?', 3, '[{"text": "Kundenfeedback einholen", "correct": true, "because": "Passt Angebote an"}, {"text": "Regelmäßiger Kontakt", "correct": true, "because": "Pflegt Beziehung"}, {"text": "Personalisierte Lösungen", "correct": true, "because": "Erfüllt Bedürfnisse"}, {"text": "Preisreduktion", "correct": false, "because": "Kurzfristig, nicht nachhaltig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die konsequente Kundenausrichtung im Relationship Marketing?', 4, '[{"text": "Höhere Kundenbindung", "correct": true, "because": "Vertrauen wächst"}, {"text": "Bessere Kundenkenntnis", "correct": true, "because": "Daten werden genutzt"}, {"text": "Wiederholungskäufe", "correct": true, "because": "Loyalität steigt"}, {"text": "Geringere Marketingkosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools fördern die konsequente Kundenausrichtung im Relationship Marketing?', 3, '[{"text": "CRM-Systeme", "correct": true, "because": "Verwalten Kundeninformationen"}, {"text": "Analyse-Software", "correct": true, "because": "Erkennt Bedürfnisse"}, {"text": "Kommunikationsplattformen", "correct": true, "because": "Ermöglichen Kontakt"}, {"text": "Produktionsplanung", "correct": false, "because": "Technisch, nicht kundenbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken entstehen, wenn die konsequente Kundenausrichtung im Relationship Marketing fehlt?', 3, '[{"text": "Verlust von Kundenloyalität", "correct": true, "because": "Beziehung schwächt sich"}, {"text": "Unzufriedenheit der Kunden", "correct": true, "because": "Bedürfnisse werden ignoriert"}, {"text": "Wettbewerbsnachteile", "correct": true, "because": "Konkurrenz überholt"}, {"text": "Technische Fehler", "correct": false, "because": "Nicht direkt verknüpft"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Relationship Marketing setzt auf langfristige Kundenbeziehungen. b) Personalisierung ist im Relationship Marketing irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Langfristigkeit ja, Personalisierung essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Im Relationship Marketing ist Kundenfeedback ein zentraler Bestandteil. b) Kurzfristige Gewinne haben Vorrang vor Kundenbindung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Feedback ja, Gewinne sekundär"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die konsequente Kundenausrichtung im Relationship Marketing fördert Vertrauen. b) Standardisierte Angebote sind der Kern dieses Ansatzes.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vertrauen ja, Standardisierung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Nachbetreuung ist im Relationship Marketing unwichtig. b) CRM-Systeme unterstützen die Kundenausrichtung.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Nachbetreuung wichtig, CRM hilfreich"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die konsequente Kundenausrichtung im Relationship Marketing erhöht die Kundenbindung. b) Sie erfordert keine Analyse von Kundenbedürfnissen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bindung ja, Analyse essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

